-- Preserve registrations independently of publication. Some groups have no hub yet.
create table public.roblox_wiki_registry (
  game_slug text primary key check (game_slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  game_name text not null check (length(btrim(game_name)) > 0),
  -- Registration can precede universe imports in managed development.
  universe_id bigint check (universe_id > 0),
  universe_names text[] not null check (cardinality(universe_names) > 0),
  sort_order integer not null default 0,
  collections jsonb not null default '[]'::jsonb check (jsonb_typeof(collections) = 'array')
);
alter table public.roblox_wiki_registry enable row level security;
revoke all on public.roblox_wiki_registry from anon, authenticated;
grant all on public.roblox_wiki_registry to service_role;

-- Generated from the ordered registry index and all 75 game modules.
-- Labels and collection sort orders use the former GAME_COLLECTIONS rules.
-- Existing page_type values remain authoritative during backfill.
insert into public.roblox_wiki_registry
  (game_slug, game_name, universe_id, universe_names, sort_order, collections)
select g->>'gameSlug', g->>'gameName',
  coalesce((g->>'universeId')::bigint,
    (select universe_id from public.wiki_pages where slug = g->>'gameSlug' limit 1),
    (select universe_id from public.wiki_collection_pages
      where wiki_slug = g->>'gameSlug' and universe_id is not null limit 1),
    (select case when count(*) = 1 then min(universe_id) else null end from public.roblox_universes
      where name = any(array(select jsonb_array_elements_text(g->'universeNames')))
         or display_name = any(array(select jsonb_array_elements_text(g->'universeNames')))
      )),
  array(select jsonb_array_elements_text(g->'universeNames')),
  (g->>'sortOrder')::integer,
  coalesce((select jsonb_agg(c || jsonb_build_object('pageType', coalesce(
    (select case when p.page_type = 'collectible' then 'collectible' else 'database' end
       from public.wiki_collection_pages p
       where p.wiki_slug = g->>'gameSlug' and p.collection_slug = c->>'slug' limit 1),
    'database')) order by ord)
   from jsonb_array_elements(g->'collections') with ordinality as entries(c, ord)), '[]'::jsonb)
from jsonb_array_elements($registry$[
