comment on table public.roblox_wiki_registry is
  'Editorial Roblox game identities and ordered collection registrations, including unpublished work. Content publishers own these rows.';

-- Keep the seeded registry complete, including groups without collections.
do $$
begin
  if (select count(*) from public.roblox_wiki_registry) <> 75
     or (select sum(jsonb_array_length(collections)) from public.roblox_wiki_registry) <> 656 then
    raise exception 'Roblox registry backfill must contain 75 groups and 656 collections';
  end if;
end;
$$;

-- Merge selected registrations atomically so parallel collection publications
-- cannot discard a different collection added to the same game.
create function public.merge_roblox_wiki_registry(
  p_game_slug text,
  p_game_name text,
  p_universe_id bigint,
  p_universe_names text[],
  p_collections jsonb,
  p_sort_order integer default null
) returns setof public.roblox_wiki_registry
language sql
security invoker
set search_path = ''
as $$
  insert into public.roblox_wiki_registry as registry
    (game_slug, game_name, universe_id, universe_names, sort_order, collections)
  values (
    p_game_slug, p_game_name, p_universe_id, p_universe_names,
    coalesce(p_sort_order, (select coalesce(max(sort_order), 0) + 1000 from public.roblox_wiki_registry)),
    p_collections
  )
  on conflict (game_slug) do update set
    game_name = excluded.game_name,
    universe_id = excluded.universe_id,
    universe_names = excluded.universe_names,
    sort_order = coalesce(p_sort_order, registry.sort_order),
    collections = (
      select coalesce(jsonb_agg(entry order by (entry->>'sortOrder')::integer, entry->>'slug'), '[]'::jsonb)
      from (
        select distinct on (entry->>'slug') entry
        from (
          select value as entry, 0 as priority from jsonb_array_elements(registry.collections)
          union all
          select value as entry, 1 as priority from jsonb_array_elements(excluded.collections)
        ) candidates
        order by entry->>'slug', priority desc
      ) merged
    )
  where registry.universe_id is null or registry.universe_id = excluded.universe_id
  returning registry.*;
$$;

revoke all on function public.merge_roblox_wiki_registry(text, text, bigint, text[], jsonb, integer) from public, anon, authenticated;
grant execute on function public.merge_roblox_wiki_registry(text, text, bigint, text[], jsonb, integer) to service_role;
